class Cache:
    def __init__(self):
        self._data = {}

    def put(self, key, value, now, ttl):
        if ttl <= 0:
            self._data[key] = (value, now, ttl)
        else:
            self._data[key] = (value, now, ttl)

    def get(self, key, now):
        if key not in self._data:
            return None
        value, insertion_time, ttl = self._data[key]
        if now >= insertion_time + ttl:
            del self._data[key]
            return None
        return value
