def parse_csv(text):
    if not text:
        return []

    records = []
    current_record = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                current_field.append(ch)
                i += 1
        else:
            if ch == '"':
                in_quotes = True
                i += 1
            elif ch == ',':
                current_record.append(''.join(current_field))
                current_field = []
                i += 1
            elif ch == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    current_record.append(''.join(current_field))
                    records.append(current_record)
                    current_record = []
                    i += 2
                else:
                    current_record.append(''.join(current_field))
                    records.append(current_record)
                    current_record = []
                    i += 1
            elif ch == '\n':
                current_record.append(''.join(current_field))
                records.append(current_record)
                current_record = []
                i += 1
            else:
                current_field.append(ch)
                i += 1

    # Handle the last field/record if the text doesn't end with a separator
    if current_field or current_record:
        current_record.append(''.join(current_field))
        records.append(current_record)

    return records
